function findMergedPrForBranch(scm, branchName) {
    var closedPRs = scm.listPrs('closed') || [];
    var mergedMatch = closedPRs.filter(function(pr) {
        return pr.head && pr.head.ref && pr.head.ref === branchName && pr.merged_at;
    });
